    const row = db.prepare('SELECT seen_at FROM worker_heartbeat WHERE id=1').get() as { seen_at: number } | undefined;
    return send(res, 200, { status: 'ok', worker: row && Date.now() - row.seen_at <= 3000 ? 'up' : 'down' });
  }
  if (pathname === '/') {
    if (req.method !== 'GET') return fail(res, 405, 'method_not_allowed', 'Method not allowed.');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' }); res.end(uiHtml); return;
  }
  if (pathname === '/api/jobs') {
    if (req.method === 'POST') return await submit(req, res);
    if (req.method === 'GET') {
      const rows = db.prepare('SELECT * FROM jobs ORDER BY created_at DESC, rowid DESC').all() as Record<string, unknown>[];
