import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, () => { stopping = true; });

// Jobs left running by a dead worker become eligible for another attempt.
db.prepare("UPDATE jobs SET status='queued', progress_completed=0, updated_at=? WHERE status='running'").run(new Date().toISOString());
const heartbeat = db.prepare(`INSERT INTO worker_heartbeat(id,seen_at) VALUES(1,?)
  ON CONFLICT(id) DO UPDATE SET seen_at=excluded.seen_at`);
console.log('worker started');

while (!stopping) {
  heartbeat.run(Date.now());
  db.exec('BEGIN IMMEDIATE');
  let job: { id: string; input: string; steps: number; fail_attempts: number; attempts: number } | undefined;
  try {
    job = db.prepare("SELECT id,input,steps,fail_attempts,attempts FROM jobs WHERE status='queued' AND available_at<=? ORDER BY created_at ASC, rowid ASC LIMIT 1")
      .get(Date.now()) as typeof job;
    if (job) {
      db.prepare("UPDATE jobs SET status='running', attempts=attempts+1, progress_completed=0, updated_at=? WHERE id=? AND status='queued'")
        .run(new Date().toISOString(), job.id);
      job.attempts += 1;
    }
    db.exec('COMMIT');
  } catch (err) {
    try { db.exec('ROLLBACK'); } catch { /* ignore */ }
    throw err;
  }
  if (!job) { await sleep(100); continue; }

  if (job.attempts <= job.fail_attempts) {
    const now = new Date().toISOString();
    if (job.attempts >= 3) {
      db.prepare("UPDATE jobs SET status='failed', error='transient failure', result_output=NULL, updated_at=? WHERE id=?")
        .run(now, job.id);
    } else {
      db.prepare("UPDATE jobs SET status='queued', progress_completed=0, available_at=?, updated_at=? WHERE id=?")
        .run(Date.now() + 500, now, job.id);
    }
    continue;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(100);
    const now = new Date().toISOString();
    db.prepare("UPDATE jobs SET progress_completed=?, updated_at=? WHERE id=? AND status='running'")
      .run(step, now, job.id);
  }
  const output = job.input.toUpperCase();
  db.prepare("UPDATE jobs SET status='completed', progress_completed=steps, result_output=?, error=NULL, updated_at=? WHERE id=? AND status='running'")
    .run(output, new Date().toISOString(), job.id);
}

heartbeat.run(Date.now());
db.close();
