<body>
  <h1>Job tracker</h1>
  <form data-testid="job-form" id="job-form">
    <label>Input <input data-testid="job-input" name="input" type="text" required></label>
    <label>Steps <input data-testid="job-steps" name="steps" type="number" min="1" max="20" step="1" value="5"></label>
    <label>Fail attempts <input data-testid="job-fail-attempts" name="failAttempts" type="number" min="0" max="5" step="1" value="0"></label>
    <button data-testid="job-submit" type="submit">Submit job</button>
    <div data-testid="form-error" role="alert"></div>
  </form>
  <h2>Jobs</h2>
  <ul data-testid="job-list" id="job-list"></ul>
  <script>
    const form = document.querySelector('[data-testid="job-form"]');
    const errorRegion = document.querySelector('[data-testid="form-error"]');
    const list = document.querySelector('[data-testid="job-list"]');
    form.addEventListener('submit', async (event) => {
      event.preventDefault();
      errorRegion.textContent = '';
      const values = new FormData(form);
      const payload = { input: values.get('input'), steps: Number(values.get('steps')), failAttempts: Number(values.get('failAttempts')) };
      try {
        const response = await fetch('/api/jobs', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
        const data = await response.json();
        if (!response.ok) {
          const fields = data.error?.fields || [];
          errorRegion.textContent = fields.length
            ? `${data.error?.message || 'Request rejected'} ${fields.map(field => `${field.field}: ${field.message}`).join(' ')}`
            : (data.error?.message || 'Request rejected');
        } else {
          form.elements.input.value = '';
          await refreshJobs();
        }
      } catch { errorRegion.textContent = 'Unable to submit the job.'; }
    });

    function makeJob(job) {
      const item = document.createElement('li');
      item.setAttribute('data-testid', 'job-item');
      item.dataset.jobId = job.id;
      const heading = document.createElement('strong');
      heading.textContent = job.input;
      item.append(heading);
      const meta = document.createElement('div'); meta.className = 'meta';
      const status = document.createElement('span'); status.setAttribute('data-testid', 'job-status'); status.textContent = job.status;
      const progress = document.createElement('span'); progress.setAttribute('data-testid', 'job-progress'); progress.textContent = `${job.progress.completed}/${job.progress.total}`;
      meta.append(status, progress); item.append(meta);
      const result = document.createElement('div'); result.setAttribute('data-testid', 'job-result');
      result.textContent = job.result?.output ?? job.error ?? '';
      item.append(result);
      return item;
    }
    async function refreshJobs() {
      try {
        const response = await fetch('/api/jobs', { cache: 'no-store' });
        if (!response.ok) return;
        const { jobs } = await response.json();
        list.replaceChildren(...jobs.map(makeJob));
      } catch { /* next poll will retry */ }
    }
    refreshJobs();
    setInterval(refreshJobs, 600);
  </script>
</body>
</html>
